"""Offline replay: what the respelling rules do to every recorded run's raw replies."""
import json, glob, sys, importlib.util, re
from collections import Counter

sys.path.insert(0, "/workspace/harness/solver")
sys.path.insert(0, "/workspace")
def load_module(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m); return m
mem = load_module("mem", "/workspace/harness/solver/tools/memory.py")

from benchmark.data.evaluators import get_evaluator

RUNS = {
    "baseline": "9f49dd7221d29df0c6f8b80f8f04a8b2b2b607f7",
    "ranked": "b539c7bec6aedea86a01cfab887fab950110c356",
    "template-free": "562ab0872291f6e171db9409b3576432d425084c",
    "spelling-check": "57a4d05c3f5fc24a9196220ef26c5254ea360077",
    "scoped-tools": "54fcbc3010c5d571ac06d028c53f4671b7219188",
    "respelling": "7dacda0afed022c6d09a60aabeaaba4b50a209cb",
    "answer-units": "268efd933a7c6b81babd03fba3aedfc05e93884f",
    "distinct": "e16a2b19433c8f309cca3d097b0cf9c1c34ee592",
    "attempts": "03d84c3861acf255d5db8a09aac363677d8a9b14",
}

FIELD = re.compile(r'("final_answer"\s*:\s*")((?:[^"\\]|\\.)*)(")')

def answer_text(content):
    """The text the middleware treats as the answer: the field, else the whole reply."""
    if not isinstance(content, str):
        return None
    if FIELD.search(content):
        return FIELD.search(content).group(2)
    return content

def raw_reply(trace):
    for m in reversed(trace["messages"]):
        if m["role"] == "assistant" and m.get("content"):
            return m["content"] if isinstance(m["content"], str) else "".join(
                b.get("text", "") for b in m["content"] if isinstance(b, dict))
    return None

def correct(task, reply, target):
    """Whether the runner would score this reply right, ignoring the guard's copy step."""
    pred = reply
    ev = get_evaluator(task)
    res = ev(pred, target)
    return bool(res["was_correct"]) if isinstance(res, dict) else bool(res)

def main():
    per_run = {}
    for name, tree in RUNS.items():
        for task in ["LawBench", "Symptom2Disease", "USPTO"]:
            path = f"/workspace/runs/{tree}/{task}/memory.json"
            try:
                examples = json.load(open(path))["examples"]
            except FileNotFoundError:
                continue
            space = mem.AnswerSpace(examples)
            if not space.repeats:
                continue
            counts = Counter()
            for f in sorted(glob.glob(f"/workspace/runs/{tree}/{task}/conversations/*/sample-*.json")):
                trace = json.load(open(f))
                if "was_correct" not in trace:
                    continue
                content = raw_reply(trace)
                if content is None:
                    continue
                text = answer_text(content)
                if text is None:
                    continue
                target = trace["target"]
                before = correct(task, text, target)
                after = correct(task, space.respell(text), target)
                counts["n"] += 1
                counts[f"{before}->{after}"] += 1
            per_run[(name, task)] = counts
    for key, counts in per_run.items():
        n = counts["n"]
        gain = counts["False->True"]; loss = counts["True->False"]
        ch = counts["True->True"] + counts["False->False"]
        print(f"{key[0]:16s} {key[1]:16s} n={n:4d} gain={gain:3d} loss={loss:3d} "
              f"unchanged={ch:4d} changed={counts['True->False']+counts['False->True']:3d}")

main()
